describe('Notification Message Rendered', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
  });

  it('should display notification when clicking the action link', () => {
    cy.get('[data-testid="click-here-link"]').click();
    cy.get('#flash-messages').should('be.visible');
    cy.get('#flash-messages').should('contain', 'Action successful');
    cy.get('#flash-messages').should('have.class', 'success');
    cy.get('#flash-messages').should('contain', 'Notification message');
    cy.get('#flash-messages').should('be.visible');
  });

  it('should dismiss notification when clicking the close icon', () => {
    cy.get('[data-testid="click-here-link"]').click();
    cy.get('#flash-messages').should('be.visible');
    cy.get('#flash-messages').should('contain', 'Action successful');
    cy.get('#flash-messages').find('[data-testid="close-icon"]').click();
    cy.get('#flash-messages').should('not.exist');
  });
});
